def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    while b:
        a, b = b, a % b
    return abs(a)

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result = ""
    for char in string:
        if char.islower():
            result += char.upper()
        elif char.isupper():
            result += char.lower()
        else:
            result += char
    return result

def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    a, b = 1, 1
    count = 0

    while True:
        if is_prime(a):
            count += 1
            if count == n:
                return a
        a, b = b, a + b

def search(lst):
    # Count frequency of each number
    freq = {}
    for num in lst:
        freq[num] = freq.get(num, 0) + 1

    # Find the greatest integer where frequency >= value itself
    result = -1
    for num, count in freq.items():
        if num > 0 and count >= num and num > result:
            result = num

    return result

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all prime factors
    prime_factors = []
    for i in range(2, a + 1):
        if a % i == 0 and is_prime(i):
            prime_factors.append(i)

    # Check if the number is product of exactly 3 primes
    if len(prime_factors) != 3:
        return False

    # Check if the product equals a
    product = prime_factors[0] * prime_factors[1] * prime_factors[2]
    return product == a

def get_row(lst, x):
    coordinates = []

    for row_idx, row in enumerate(lst):
        for col_idx, value in enumerate(row):
            if value == x:
                coordinates.append((row_idx, col_idx))

    # Sort by row ascending, then by column descending
    coordinates.sort(key=lambda coord: (coord[0], -coord[1]))

    return coordinates
